-- GENERATED by scripts/generate-seed.js on 2026-08-22. Do not edit by hand.
-- Regenerate with:  node scripts/generate-seed.js
--
-- 12 employees across 4 departments, attendance from 2026-01-01 to 2026-08-22,
-- 29 leave requests, 15 salary versions, 24 payslips.
--
-- Every demo account signs in with the password: Dayflow@2026
-- All are ACTIVE with email_verified_at set, so no verification step is needed.
--
-- Leave balances are NOT stored anywhere. They are the SUM of the ledger rows below,
-- read through v_leave_balances (CLAUDE.md §1.1).
--
-- Intended for a freshly migrated database. Running it twice raises an exception
-- rather than duplicating the ledger, which would silently corrupt every balance.

BEGIN;

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM users WHERE employee_code LIKE 'DF-%') THEN
    RAISE EXCEPTION 'Demo data is already present. Start from a clean database: npm run db:reset && npm run migrate && npm run seed';
  END IF;
END $$;

CREATE TEMP TABLE seed_emp (code TEXT PRIMARY KEY, user_id BIGINT, employee_id BIGINT) ON COMMIT DROP;
CREATE TEMP TABLE seed_req (key TEXT PRIMARY KEY, request_id BIGINT) ON COMMIT DROP;
CREATE TEMP TABLE seed_sal (key TEXT PRIMARY KEY, version_id BIGINT) ON COMMIT DROP;

