-- ---------------------------------------------------------------------------
-- Payslips for the two most recent complete months.
-- Amounts are computed by the SAME expression payroll.queries.js uses, so a seeded
-- payslip and one produced by POST /payroll/runs agree to the paisa.
-- ---------------------------------------------------------------------------
WITH comp AS (
  SELECT sc.kind, sc.code, sc.label, ROUND(sc.monthly_amount * 21::numeric / NULLIF(22, 0)::numeric, 2) AS amount
  FROM salary_components sc WHERE sc.salary_version_id = (SELECT version_id FROM seed_sal WHERE key = 'DF-001-v1')
), totals AS (
  SELECT COALESCE(SUM(amount) FILTER (WHERE kind = 'EARNING'), 0) AS gross,
         COALESCE(SUM(amount) FILTER (WHERE kind = 'DEDUCTION'), 0) AS deductions FROM comp
), slip AS (
                        gross_earnings, total_deductions, net_pay, generated_by, generated_at)
  SELECT (SELECT employee_id FROM seed_emp WHERE code = 'DF-001'), DATE '2026-06-01', (SELECT version_id FROM seed_sal WHERE key = 'DF-001-v1'), 21, 1,
         t.gross, t.deductions, t.gross - t.deductions, (SELECT user_id FROM seed_emp WHERE code = 'DF-001'),
         '2026-06-01 18:00:00+05:30'::timestamptz
  FROM totals t RETURNING id
)
SELECT slip.id, comp.code, comp.label, comp.kind, comp.amount FROM slip, comp;
